DELETE FROM log
WHERE type = #{type}
AND CAST(SYSTIMESTAMP AS TIMESTAMP) - NUMTODSINTERVAL(#{days}, 'DAY') > created_at

mapper.sql:
WHERE type != 'ACCESS'
AND 

    AND type = #{filter.type}


    AND success = #{filter.successYn}


    AND INSTR(LOWER(employee_name), LOWER(#{filter.employeeName})) > 0


    AND INSTR(LOWER(message), LOWER(#{filter.keyword})) > 0


    AND created_at >= #{filter.startDate}


    AND #{filter.endDateExclusive} > created_at
